CUDA.device!(0)
CUDA.context()
const SS_STREAM=CUDA.CuStream()
CUDA.stream!(SS_STREAM)
@assert Base.ENDIAN_BOM == 0x04030201
const SS_PAD=256
const SS_PAD_WORDS=64
const SS_WIDTH=131072
const SS_SENTINEL=typemax(UInt32)
const SS_COUNTS=zeros(Int,2)
@inline ss_lower(c::UInt8) = 0x41 <= c <= 0x5a ? c+0x20 : c
@inline ss_upper(c::UInt8) = 0x61 <= c <= 0x7a ? c-0x20 : c

# Translation of the original host Boyer–Moore–Horspool routine; independent
# oracle files are generated by a different every-start Python algorithm.
function ss_bmh(text::Vector{UInt8},pattern::Vector{UInt8})
    n=length(text);p=length(pattern);last=p-1;skip=fill(p,256)
    for i in 0:last-1
        skip[Int(ss_upper(pattern[i+1]))+1]=last-i
        skip[Int(ss_lower(pattern[i+1]))+1]=last-i
    end
    out=UInt32[];position=0
    while n-position>last
        j=last;scan=last+position
        while ss_lower(text[scan+1])==ss_lower(pattern[j+1])
            j-=1
            if scan==position
                push!(out,UInt32(position));break
            end
            scan-=1
        end
        position+=scan==position ? 1 : skip[Int(text[last+position+1])+1]
    end
    out
end

ss_json(x::Bool)=x ? "true" : "false"
ss_json(::Nothing)="null"
ss_json(x::Integer)=string(x)
ss_json(x::AbstractFloat)=isfinite(x) ? string(x) : error("NonfiniteJSONvalue")
ss_json(x::AbstractString)="\""*replace(String(x),"\\"=>"\\\\","\""=>"\\\"","\n"=>"\\n","\r"=>"\\r","\t"=>"\\t")*"\""
ss_json(x::AbstractVector)="["*join(ss_json.(x),",")*"]"
ss_json(x::AbstractDict)="{"*join([ss_json(string(k))*":"*ss_json(v) for (k,v) in x],",")*"}"
function ss_read_words(path)
    n=filesize(path);n%4==0||error("Badwordinputlength")
    out=Vector{UInt32}(undef,n÷4)
    open(path,"r")do io;read!(io,out);eof(io)||error("Trailingwordinput");end
    out
end
function ss_save(path,data)
    open(path,"w")do io;write(io,data);end
    Dict{String,Any}("path"=>path,"bytes"=>filesize(path),"sha256"=>bytes2hex(sha256(read(path))))
end
function ss_capture(private,trial,caseid,role,data)
    path=joinpath(private,"trial$(trial)_case$(caseid)_$(role).bin")
    out=ss_save(path,data);out["role"]=role;out
end
ss_physical_bytes(v)=collect(reinterpret(UInt8,v))
function ss_guards(v)
    b=ss_physical_bytes(v)
    all(==(0xa5),@view(b[1:SS_PAD]))&&all(==(0x5a),@view(b[end-SS_PAD+1:end]))
end
function ss_u8_initial(n)
    vcat(fill(UInt8(0xa5),SS_PAD),fill(UInt8(0xff),n),fill(UInt8(0x5a),SS_PAD))
end
function ss_u32_initial(n)
    vcat(fill(UInt32(0xa5a5a5a5),SS_PAD_WORDS),fill(SS_SENTINEL,n),fill(UInt32(0x5a5a5a5a),SS_PAD_WORDS))
end

function ss_run_case(c,caseid,trial,private,all_inputs,all_outputs)
    text=read(c.path);pattern=collect(codeunits(c.pattern));gold=ss_read_words(c.oracle)
    n=length(text);p=length(pattern);n>=p>0||error("Sourcestringdomain")
    (p==1||p>16)||error("Sourcebuildrejectspatternlength2through16")
    source_cpu=ss_bmh(text,pattern)
    source_cpu==gold||error("HostBMHrefdiffersfromindependentnaiveoracle")
    N=n-p+1;groups=cld(N,SS_WIDTH)
    full=(CuArray(ss_u8_initial(n)),CuArray(ss_u8_initial(p)),CuArray(ss_u32_initial(groups)),CuArray(ss_u32_initial(N)))
    views=(view(full[1],SS_PAD+1:SS_PAD+n),view(full[2],SS_PAD+1:SS_PAD+p),view(full[3],SS_PAD_WORDS+1:SS_PAD_WORDS+groups),view(full[4],SS_PAD_WORDS+1:SS_PAD_WORDS+N))
    copyto!(views[1],text);copyto!(views[2],pattern)
    before=map(Array,full);captures=Dict{String,Any}[]
    for k in 1:4
        push!(captures,ss_capture(private,trial,caseid,"before_allocation$(k-1)",before[k]))
    end
    initial_ok=all(ss_guards,before)&&collect(@view(before[1][SS_PAD+1:SS_PAD+n]))==text&&collect(@view(before[2][SS_PAD+1:SS_PAD+p]))==pattern
    initial_ok &=all(==(SS_SENTINEL),@view(before[3][SS_PAD_WORDS+1:SS_PAD_WORDS+groups]))&&all(==(SS_SENTINEL),@view(before[4][SS_PAD_WORDS+1:SS_PAD_WORDS+N]))
    initial_ok||error("ActualinitializedGPUinput/guardgatefailed")
    append!(all_inputs,UInt32[caseid,n,p,c.repeats,groups,N,SS_WIDTH,SS_PAD,SS_SENTINEL])
    append!(all_inputs,UInt32.(before[1]));append!(all_inputs,UInt32.(before[2]));append!(all_inputs,before[3]);append!(all_inputs,before[4])
    mode=p==1 ? Val(0) : Val(1);old_counts=copy(SS_COUNTS)
    CUDA.device_synchronize(;blocking=true)
    start=time_ns()
    for _ in 1:c.repeats
        ss_launch(mode,views[1],views[2],views[4],views[3],Int32(n),Int32(p),Int32(SS_WIDTH),groups)
    end
    CUDA.device_synchronize(;blocking=true)
    elapsed=Float64(time_ns()-start)*1e-9
    executed=SS_COUNTS.-old_counts
    executed==(p==1 ? [c.repeats,0] : [0,c.repeats])||error("ActualsourceGPUrepeatcountchanged")
    after=map(Array,full)
    for k in 1:4
        push!(captures,ss_capture(private,trial,caseid,"after_allocation$(k-1)",after[k]))
    end
    guards=all(ss_guards,after);unchanged=after[1]==before[1]&&after[2]==before[2]
    counts=collect(@view after[3][SS_PAD_WORDS+1:SS_PAD_WORDS+groups]);raw=collect(@view after[4][SS_PAD_WORDS+1:SS_PAD_WORDS+N])
    expected_counts=zeros(UInt32,groups)
    for pos in gold
        Int(pos)<N||error("Oraclebounds")
        expected_counts[Int(pos)÷SS_WIDTH+1]+=UInt32(1)
    end
    bijection=counts==expected_counts;inactive=true
    entries=Tuple{UInt32,UInt32}[];sizehint!(entries,length(gold))
    for g in 0:groups-1
        base=g*SS_WIDTH;capacity=min(SS_WIDTH,N-base);count=Int(counts[g+1])
        count<=capacity||error("GPUcountoutsideallocatedgroup")
        for j in 0:count-1
            physical=base+j;pos=Int(raw[physical+1])
            base<=pos<base+capacity||error("GPUmatchoutsidegroupdomain")
            for k in 0:p-1
                bijection &=ss_lower(after[1][SS_PAD+pos+k+1])==ss_lower(after[2][SS_PAD+k+1])
            end
            push!(entries,(UInt32(pos),UInt32(physical)))
        end
        for j in count:capacity-1
            inactive &=raw[base+j+1]==SS_SENTINEL
        end
    end
    sort!(entries);canonical=UInt32[x[1] for x in entries];permutation=UInt32[x[2] for x in entries]
    bijection &=canonical==gold&&allunique(canonical)
    reconstructed=fill(SS_SENTINEL,N)
    for i in eachindex(canonical);reconstructed[Int(permutation[i])+1]=canonical[i];end
    bijection &=reconstructed==raw
    push!(captures,ss_capture(private,trial,caseid,"complete_canonical_to_physical_slot_permutation_u32",permutation))
    # Original source compaction followed by sorting, with safe overlapping copy.
    host=copy(raw);total=Int(counts[1])
    for g in 1:groups-1
        found=Int(counts[g+1])
        if found>0
            copied=copy(@view host[g*SS_WIDTH+1:g*SS_WIDTH+found])
            copyto!(host,total+1,copied,1,found);total+=found
        end
    end
    sort!(@view host[1:total])
    source_final=total==length(source_cpu)&&collect(@view(host[1:total]))==source_cpu&&source_cpu==gold
    independent_host=copy(raw);written=Int(counts[1])
    for g in 1:groups-1
        found=Int(counts[g+1]);copyto!(independent_host,written+1,raw,g*SS_WIDTH+1,found);written+=found
    end
    sort!(@view independent_host[1:written]);source_final &=host==independent_host
    push!(captures,ss_capture(private,trial,caseid,"complete_source_host_final_result_u32",host))
    append!(all_outputs,UInt32[caseid,groups,total]);append!(all_outputs,counts);append!(all_outputs,@view(host[1:total]))
    correct=initial_ok&&guards&&unchanged&&inactive&&bijection&&source_final
    row=Dict{String,Any}("case"=>caseid,"text_bytes"=>n,"pattern_bytes"=>p,"repeats"=>c.repeats,"workgroups"=>groups,"matches"=>total,"time_seconds"=>elapsed,"source_final_sorted_and_independent_all_position_oracle"=>source_final&&bijection,"complete_lossless_raw_bijection"=>bijection,"all_guard_bytes_checked"=>guards,"all_inactive_result_slots_initial_sentinel"=>inactive,"full_input_allocations_unchanged"=>unchanged,"source_GPU_dispatches"=>executed,"raw_output_identity_claim"=>false,"complete_physical_captures"=>captures)
    open(joinpath(private,"trial$(trial)_case$(caseid)_complete_case.json"),"w")do io;write(io,ss_json(row)*"\n");end
    println(stderr,"SS independent case=",caseid," matches=",total," exact=",source_final," guards=",guards," inactive=",inactive," bijection=",bijection);flush(stderr)
    for gpu in full;CUDA.unsafe_free!(gpu);end
    row,correct
end
function ss_study()
    length(ARGS)==2||error("Usage: main.jl FIXTURES PRIVATE_CAPTURE_ROOT")
    fixtures=abspath(ARGS[1]);root=abspath(ARGS[2]);mkpath(root);private=mktempdir(root;prefix="process_$(getpid())_",cleanup=false)
    println(stderr,"STUDY_PRIVATE_RUN ",private)
    cases=NamedTuple[]
    for line in readlines(joinpath(fixtures,"cases.tsv"))
        f=String.(split(line,'\t'));length(f)==5||error("Casesformat")
        push!(cases,(name=f[1],repeats=parse(Int,f[2]),path=f[3],pattern=f[4],oracle=f[5]))
    end
    length(cases)==7||error("Casecount")
    canonical_input=ss_read_words(joinpath(fixtures,"canonical_actual_input_prefix.u32.bin"))
    println("STUDY_IMPLEMENTATION pure_Julia_host=true native_controller=false native_GPU_fallback=false actual_source_CPU_BMH_and_sort_translated=true CUDA_explicit_owned_serial_stream=true context_completion_blocking=true")
    for trial in 0:5
        inputs=UInt32[];outputs=UInt32[];rows=Dict{String,Any}[];correct=true;elapsed=0.0
        for (i,c)in enumerate(cases)
            row,pass=ss_run_case(c,i-1,trial,private,inputs,outputs);push!(rows,row);correct &=pass;elapsed+=row["time_seconds"]
        end
        correct &=inputs==canonical_input
        artifact=vcat(inputs,outputs);path=trial==0 ? joinpath(private,"warmup_fullstate.u32.bin") : "output_trial$(trial).bin";ss_save(path,artifact)
        if trial==0
            println(stderr,"SS fullsourcewarmup correct=",correct);correct||error("Fullsourcewarmuprejected");continue
        end
        record=Dict{String,Any}("trial"=>trial,"time_seconds"=>elapsed,"correct"=>correct,"checked_values"=>length(artifact),"max_abs_error"=>nothing,"max_rel_error"=>nothing,"timing_region"=>"full_source_repeat_loops_host_launch_control_and_context_completion","jit_excluded"=>true,"internal_repeats"=>20006,"raw_output_identity_claim"=>false,"complete_keyed_value_bijection_checked"=>true,"cases"=>rows,"output_artifact"=>Dict("path"=>path,"dtype"=>"uint32","count"=>length(artifact),"byte_order"=>"little"))
        println("STUDY_TRIAL ",ss_json(record));flush(stdout);correct||error("Fullsourcecheckedtrialrejected")
    end
    println("STUDY_AUTHORED_DEVICE_DISPATCHES ",sum(SS_COUNTS)," per_entry=",SS_COUNTS)
    SS_COUNTS==[12,120024]||error("Fullsourcewarmup+fiveactualdispatchcountdiffers")
end
